import { promises as fs } from 'fs';
import path from 'path';
import { describe, expect, it } from 'vitest';

async function filesUnder(root: string): Promise<string[]> {
  const result: string[] = [];
  const visit = async (directory: string) => {
    for (const entry of await fs.readdir(directory, { withFileTypes: true })) {
      const target = path.join(directory, entry.name);
      if (entry.isDirectory()) await visit(target);
      else if (entry.isFile()) result.push(target);
    }
  };
  await visit(root);
  return result.sort();
}

async function combined(files: string[]): Promise<string> {
  return (await Promise.all(files.map((file) => fs.readFile(file, 'utf8')))).join('\n');
}

async function nativeSpec(name: string): Promise<string> {
  return fs.readFile(path.resolve('docs', 'comet', 'specs', name, 'spec.md'), 'utf8');
}

describe('Comet Native isolation boundaries', () => {
  it('keeps the Native domain independent from Classic and OpenSpec execution', async () => {
    const files = (await filesUnder(path.resolve('domains', 'comet-native'))).filter((file) =>
      file.endsWith('.ts'),
    );
    const source = await combined(files);

    expect(source).not.toMatch(/\bfrom\s+['"][^'"]*comet-classic[^'"]*['"]/u);
    expect(source).not.toMatch(/spawn(?:Sync)?\([^)]*openspec|execFile(?:Sync)?\([^)]*openspec/iu);
    expect(source).not.toMatch(/openspec[\\/]changes/iu);
    expect(source).toContain("'.comet/config.yaml'");
    expect(new Set(source.match(/\.comet\/[A-Za-z0-9._/-]+/gu) ?? [])).toEqual(
      new Set([
        '.comet/config.yaml',
        '.comet/current-change.json',
        '.comet/runtime',
        '.comet/runtime/',
      ]),
    );
  });

  it('ships a self-contained Skill and runtime with no external workflow invocation', async () => {
    const skillFiles = [
      ...(await filesUnder(path.resolve('assets', 'skills', 'comet-native'))),
      ...(await filesUnder(path.resolve('assets', 'skills-zh', 'comet-native'))),
    ].filter((file) => /\.(?:md|mjs)$/u.test(file));
    const source = await combined(skillFiles);

    expect(source).not.toMatch(
      /requiredSkillCalls|openspec|(?<!\\\.)superpowers|grill-me|brainstorming|test-driven-development|subagent-driven-development/iu,
    );
    expect(source).not.toMatch(/comet\s+(?:state|guard|handoff)\b/iu);
  });

  it('keeps both workflow domains independent below the entry seam', async () => {
    const [nativeSource, classicSource] = await Promise.all([
      combined(
        (await filesUnder(path.resolve('domains', 'comet-native'))).filter((file) =>
          file.endsWith('.ts'),
        ),
      ),
      combined(
        (await filesUnder(path.resolve('domains', 'comet-classic'))).filter((file) =>
          file.endsWith('.ts'),
        ),
      ),
    ]);

    expect(nativeSource).not.toMatch(/\bfrom\s+['"][^'"]*comet-classic[^'"]*['"]/u);
    expect(classicSource).not.toMatch(/\bfrom\s+['"][^'"]*comet-native[^'"]*['"]/u);
    expect(nativeSource).not.toMatch(/\bfrom\s+['"][^'"]*comet-entry[^'"]*['"]/u);
    expect(classicSource).not.toMatch(/\bfrom\s+['"][^'"]*comet-entry[^'"]*['"]/u);
    expect(nativeSource).toContain('../workflow-contract/current-selection.js');
    expect(classicSource).toContain('../workflow-contract/current-selection.js');
    expect(nativeSource).toContain('../../platform/process/hook-adapter.js');
    expect(classicSource).toContain('../../platform/process/hook-adapter.js');
  });

  it('keeps canonical Native specs on the portable verification architecture', async () => {
    const [verification, loop, storage, resume, scope, workspace, init, parallel] =
      await Promise.all([
        nativeSpec('native-verification-evidence'),
        nativeSpec('native-completion-loop'),
        nativeSpec('native-runtime-storage'),
        nativeSpec('native-ambient-resume'),
        nativeSpec('native-scope-reopen'),
        nativeSpec('native-shape-workspace-isolation'),
        nativeSpec('native-init-workspace-defaults'),
        nativeSpec('native-parallel-worktree-tests'),
      ]);
    const canonical = [verification, loop, storage, resume, scope, workspace, init, parallel].join(
      '\n',
    );

    expect(verification).toContain('reviewer execution ref 必须与 Builder execution ref 不同');
    expect(verification).toContain('Runtime 拒绝 scope 内缺失、重复或未知 ID');
    expect(verification).toContain('Archive 不重新运行检查或 Verifier');
    expect(loop).toContain('Native 的 Build 与 Verify 循环');
    expect(loop).toContain('连续无进展和总失败轮次继续使用现有停止上限');
    expect(loop).toContain('修复范围通过后自动进入最终全量 Verify');
    expect(storage).toContain('一个 active change 只有一份可携带权威：`comet-state.yaml`');
    expect(storage).toContain('│   ├── state.json');
    expect(storage).toContain('Archive 不重新运行必要检查或 Verifier');
    expect(resume).toContain('本机 Runtime 缺失不能使可同步的 active change 消失');
    expect(scope).toContain('实现继续使当前候选失效并返回 Build');
    expect(scope).toContain('正式需求修改返回 Shape');
    expect(workspace).toContain('portable workspace binding');
    expect(init).toContain('!.comet/config.yaml');
    expect(parallel).toContain('Builder/Verifier separation');

    expect(canonical).not.toMatch(
      /contractHash|approved_contract_hash|implementation_scope|verification_evidence|partial_allowance|base_hash|baseline-manifest\.json|trajectory\.jsonl|checkpoint-journal\.json|typed receipts|Archive freshness/iu,
    );
  });
});

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';

async function typescriptFiles(root: string): Promise<string[]> {
  const entries = await fs.readdir(root, { withFileTypes: true });
  const nested = await Promise.all(
    entries.map(async (entry) => {
      const target = path.join(root, entry.name);
      if (entry.isDirectory()) return typescriptFiles(target);
      return entry.isFile() && entry.name.endsWith('.ts') ? [target] : [];
    }),
  );
  return nested.flat().sort();
}

// The old boundary asserted the removed snapshot/receipt providers. v4 uses
// the platform spawn adapter and portable Runtime tests for this contract.
describe('Native self-contained runtime boundary (legacy)', () => {
  it.skip('keeps process execution inside the bounded snapshot and receipt providers', async () => {
    const root = path.resolve('domains', 'comet-native');
    const files = await typescriptFiles(root);
    const sources = new Map(
      await Promise.all(
        files.map(
          async (file) =>
            [
              path.relative(root, file).replaceAll('\\', '/'),
              await fs.readFile(file, 'utf8'),
            ] as const,
        ),
      ),
    );
    const processFiles = [...sources]
      .filter(([, source]) => /(?:node:)?child_process/u.test(source))
      .map(([file]) => file);
    const snapshot = sources.get('native-snapshot.ts');
    const receiptRuntime = sources.get('native-verification-receipt-runtime.ts');
    const gitProvenance = sources.get('native-git-provenance.ts');

    expect(processFiles).toEqual([
      'native-git-provenance.ts',
      'native-snapshot.ts',
      'native-verification-receipt-runtime.ts',
    ]);
    expect(snapshot).toBeDefined();
    expect(receiptRuntime).toBeDefined();
    expect(gitProvenance).toBeDefined();
    expect(snapshot).toContain("import { spawn, type ChildProcess } from 'node:child_process';");
    expect(snapshot).not.toMatch(/\b(?:execFile|execSync|execFileSync|fork|spawnSync)\s*\(/u);
    expect(receiptRuntime).toContain('env: { ...process.env }');
    expect(receiptRuntime).toContain('shell: false');
    expect(receiptRuntime).toContain('COMET_NATIVE_COMMAND_PAYLOAD');
    expect(receiptRuntime).toContain('resolveWindowsCommand');
    expect(receiptRuntime).not.toContain('sanitizedAutomatedCommandEnvironment');
    expect(receiptRuntime).toContain('terminateProcessTree(child)');
    expect(gitProvenance).toContain("execFileSync('git'");
    expect(gitProvenance).toContain('maxBuffer: 2 * 1024 * 1024');
    expect(gitProvenance).toContain('windowsHide: true');
    expect(gitProvenance).not.toContain('shell: true');

    const processProviderFiles = new Set([
      'native-git-provenance.ts',
      'native-snapshot.ts',
      'native-verification-receipt-runtime.ts',
    ]);
    const sourcesOutsideProcessProviders = [...sources]
      .filter(([file]) => !processProviderFiles.has(file))
      .map(([, source]) => source)
      .join('\n');
    expect(sourcesOutsideProcessProviders).not.toMatch(
      /\b(?:spawn|execFile|execSync|execFileSync|fork|spawnSync)\s*\(/u,
    );
    expect(sourcesOutsideProcessProviders).not.toContain('gitProcess');

    const combined = [...sources.values()].join('\n');
    expect(sourcesOutsideProcessProviders).not.toMatch(/(?:^|[,{]\s*)shell\s*:/mu);
    expect(combined).not.toMatch(/runSafeCommand|inspectGitRepository|GitRepositoryInspection/iu);
    expect(combined).not.toMatch(
      /(?:^|[/'"])(?:comet-classic|openspec)(?:[/'"]|$)|superpowers|assets\/skills|\.agents\/skills|\.comet\/skills/imu,
    );
  });

  it.skip('pins Native snapshot processes to read-only Git arguments and bounded termination', async () => {
    const source = await fs.readFile(
      path.resolve('domains', 'comet-native', 'native-snapshot.ts'),
      'utf8',
    );
    const normalized = source.replace(/\s+/gu, ' ');
    const normalizedArrays = normalized
      .replace(/\[\s+/gu, '[')
      .replace(/\s+\]/gu, ']')
      .replace(/,\]/gu, ']');
    const occurrences = (pattern: RegExp): number => source.match(pattern)?.length ?? 0;
    const literalOccurrences = (value: string): number => normalizedArrays.split(value).length - 1;

    // One Git launcher and one trusted Windows process-tree terminator. Adding another spawn
    // site must make this repository boundary test fail and receive an explicit security review.
    expect(occurrences(/\bspawn\s*\(/gu)).toBe(2);
    expect(normalized).toContain("gitProcess: options.gitProcess ?? { command: 'git' }");
    expect(normalized).toContain(
      "spawn( adapter.command, [...(adapter.argsPrefix ?? []), '-C', projectRoot, ...args], { stdio: [input ? 'pipe' : 'ignore', 'pipe', 'pipe'], windowsHide: true, detached: process.platform !== 'win32', }, )",
    );
    expect(normalized).toContain(
      "spawn(taskkill, ['/pid', String(pid), '/t', '/f'], { stdio: 'ignore', windowsHide: true, })",
    );
    expect(normalized).toContain("path.win32.join(systemRoot, 'System32', 'taskkill.exe')");

    // These counts include each helper declaration. Every actual Git invocation below is
    // therefore accounted for by one of the fixed, read-only argument vectors.
    expect(occurrences(/\brunGitNullRecords\s*\(/gu)).toBe(6);
    expect(occurrences(/\brunGitBoundedOutput\s*\(/gu)).toBe(5);
    expect(occurrences(/\brunGitHasOutput\s*\(/gu)).toBe(2);
    expect(literalOccurrences("['ls-files', '--stage', '-z', ...pathspecs]")).toBe(2);
    expect(
      literalOccurrences(
        "['ls-files', '--cached', '--others', '--exclude-standard', '-z', ...pathspecs]",
      ),
    ).toBe(1);
    // Snapshot capture checks unstaged modifications before reuse and again at
    // the final fence so a concurrently dirtied reused file is invalidated.
    expect(literalOccurrences("['ls-files', '--modified', '-z']")).toBe(2);
    expect(literalOccurrences("['ls-files', '-v', '-z']")).toBe(1);
    expect(literalOccurrences("['check-ignore', '--no-index', '-z', '--stdin']")).toBe(1);
    expect(literalOccurrences("['rev-parse', '--is-inside-work-tree']")).toBe(1);
    expect(literalOccurrences("['rev-parse', '--verify', 'HEAD']")).toBe(1);
    expect(
      literalOccurrences("['status', '--porcelain=v1', '-z', '--untracked-files=normal']"),
    ).toBe(1);

    expect(normalized).toContain('const DEFAULT_NATIVE_SNAPSHOT_EXECUTION_BUDGET_MS = 60_000');
    expect(normalized).toContain('const GIT_LIST_STDERR_LIMIT = 64 * 1024');
    expect(normalized).toContain('const GIT_TEXT_STDOUT_LIMIT = 64 * 1024');
    expect(normalized).toContain("child.once('close', resolve)");
    expect(normalized).toContain('termination = terminateNativeProcessTree(child, adapter)');
  });

  it.skip('routes every Native Run file through the protected Native adapter', async () => {
    const root = path.resolve('domains', 'comet-native');
    const files = (await typescriptFiles(root)).filter(
      (file) => path.basename(file) !== 'native-run-store.ts',
    );
    const sources = await Promise.all(files.map((file) => fs.readFile(file, 'utf8')));
    const combined = sources.join('\n');

    expect(combined).not.toMatch(/from ['"]\.\.\/engine\/(?:run-store|storage-run)\.js['"]/u);
    const adapter = await fs.readFile(path.join(root, 'native-run-store.ts'), 'utf8');
    expect(adapter).toContain('containedRoot: options.changeDir');
    expect(adapter).not.toMatch(/\b(?:readRunStateAt|writeRunStateAt|removeRunStateAt)\b/u);
    for (const ref of [
      'stateRef',
      'trajectoryRef',
      'checkpointRef',
      'pendingRef',
      'contextRef',
      'artifactsRef',
    ]) {
      expect(adapter).toContain(`runFile(changeDir, '${ref}'`);
    }
  });

  it('routes v4 checks through the platform process adapter', async () => {
    const executor = await fs.readFile(
      path.resolve('domains', 'comet-native', 'native-check-executor.ts'),
      'utf8',
    );
    const runtime = await fs.readFile(
      path.resolve('domains', 'comet-native', 'native-portable-runtime.ts'),
      'utf8',
    );
    expect(executor).toContain("from '../../platform/process/spawn-command.js'");
    expect(executor).toContain('terminateProcessTree');
    expect(runtime).toContain('executeNativePortableCheckPlan');
    expect(runtime).not.toContain('buildNativeVerificationReceipt');
  });
});

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, test, vi } from 'vitest';
import { JsonFilePluginStorageStore } from '../../../platform/fs/plugin-store.js';
import { resolveStableProjectId } from '../../../platform/paths/project-identity.js';
import type { AgentExperienceEvent } from '../../../domains/agent-learning/index.js';

const captured = vi.hoisted(() => ({ events: [] as AgentExperienceEvent[], projectId: '' }));
vi.mock('../../../domains/comet-plugin/comet.js', async (original) => ({
  ...(await original<object>()),
  createDefaultCometPluginBridge: async () => ({
    currentProjectId: captured.projectId,
    currentLanguage: 'en',
    pluginRuntime: {
      enqueueEvents: async (events: AgentExperienceEvent[]) => {
        captured.events.push(...events);
      },
    },
    dispatchExperience: async () => {},
  }),
}));
import {
  areCometWorkflowResultsProcessed,
  recordCometWorkflowResult,
} from '../../../domains/comet-entry/plugin-context.js';
let root: string;
let storage: JsonFilePluginStorageStore;
let checkpoint: Parameters<typeof recordCometWorkflowResult>[0];
beforeEach(async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-receipt-'));
  vi.spyOn(os, 'homedir').mockReturnValue(root);
  captured.projectId = resolveStableProjectId(root);
  captured.events = [];
  storage = new JsonFilePluginStorageStore(path.join(root, '.comet', 'plugins', 'storage'));
  checkpoint = {
    projectRoot: root,
    workflow: 'native',
    changeId: 'one',
    command: 'next',
    success: true,
    artifactRefs: ['plan.md'],
  };
  await recordCometWorkflowResult({ ...checkpoint, captureOnly: true });
});
afterEach(async () => {
  vi.restoreAllMocks();
  await fs.rm(root, { recursive: true, force: true });
});
async function save(status = 'processed', events = captured.events, scope = 'project') {
  await (
    await storage.open(
      'comet.agent-learning',
      scope,
      scope === 'project' ? captured.projectId : undefined,
    )
  ).write({
    version: 2,
    events,
    reflections: Object.fromEntries(
      events.map((event) => [event.eventId, { status, attempts: 1, updatedAt: event.occurredAt }]),
    ),
  });
}
const read = (results?: (typeof checkpoint)[]) =>
  areCometWorkflowResultsProcessed(results ?? [checkpoint], new AbortController().signal);
test.skipIf(process.platform === 'win32')(
  'reuses durable processed receipts across reads without writing or loading Providers',
  async () => {
    await save();
    const file = path.join(
      root,
      '.comet',
      'plugins',
      'storage',
      `comet.agent-learning-project-${captured.projectId}.json`,
    );
    const before = await fs.stat(file);
    expect(await read()).toBe(true);
    expect(await read()).toBe(true);
    expect((await fs.stat(file)).mtimeMs).toBe(before.mtimeMs);
    expect(captured.events).toHaveLength(1);
  },
);
test.each(['pending', 'processing', 'waiting', 'failed'])('retries %s learning', async (status) => {
  await save(status);
  expect(await read()).toBe(false);
});
test('rejects changed evidence, scope, project identity, and missing events', async () => {
  expect(await read()).toBe(false);
  await save();
  expect(await read([{ ...checkpoint, artifactRefs: ['changed.md'] }])).toBe(false);
  await save('processed', [{ ...captured.events[0]!, projectId: 'other' }]);
  expect(await read()).toBe(false);
  await save('processed', [{ ...captured.events[0]!, scope: 'user' }]);
  expect(await read()).toBe(false);
});
test('requires all batch events, and preserves pending personal reflection', async () => {
  await save();
  expect(await read([checkpoint, { ...checkpoint, eventType: 'review.resolved' }])).toBe(false);
  await save('pending', [{ ...captured.events[0]!, scope: 'user', projectId: undefined }], 'user');
  expect(await read()).toBe(false);
});
test('fails closed for malformed and oversized journals', async () => {
  const source = await storage.open('comet.agent-learning', 'project', captured.projectId);
  await source.write({ broken: true });
  expect(await read()).toBe(false);
  await source.write({ padding: 'x'.repeat(256 * 1024) });
  expect(await read()).toBe(false);
});

test('leaves large checkpoint batches and evidence to the bounded worker', async () => {
  await save();
  expect(await read([checkpoint, checkpoint, checkpoint, checkpoint])).toBe(false);
  expect(
    await read([
      { ...checkpoint, changedPaths: Array.from({ length: 129 }, (_, i) => `file-${i}`) },
    ]),
  ).toBe(false);
  expect(await read([{ ...checkpoint, changedPaths: ['x'.repeat(64 * 1024)] }])).toBe(false);
});

import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { beforeEach, afterEach, it, expect, vi } from 'vitest';
import { getCurrentVersion } from '../../../platform/version/version.js';
import {
  prepareWorkflowApplicationPlan,
  compileWorkflowApplication,
  verifyWorkflowApplicationArtifactContracts,
  assertWorkflowVerificationCases,
  type WorkflowApplicationProposal,
  prepareWorkflowApplicationExample,
} from '../../../domains/workflow-generation/index.js';
import { hashRuntimeValue } from '../../../domains/engine/runtime.js';

let scratch: string, project: string;
beforeEach(async () => {
  scratch = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-artifact-creator-'));
  project = path.join(scratch, 'project');
  await fs.mkdir(path.join(project, 'node_modules/@rpamis'), { recursive: true });
  await fs.symlink(process.cwd(), path.join(project, 'node_modules/@rpamis/comet'), 'junction');
  vi.stubEnv('COMET_DATA_DIR', path.join(scratch, 'data'));
});
afterEach(async () => {
  vi.unstubAllEnvs();
  await fs.rm(scratch, { recursive: true, force: true });
});
function proposal(alwaysPass = false): WorkflowApplicationProposal {
  const good = '# 目标\n\n业务已完成\n\n## 验收\n\n核对实际文件\n';
  return {
    schema: 'comet.workflow.application.plan.v1',
    manifest: {
      schema: 'comet.workflow.application.v1',
      id: 'artifact-demo',
      version: '1',
      base: 'standalone',
      runtimeVersion: getCurrentVersion(),
      entrySkill: 'SKILL.md',
      module: 'application.mjs',
      skills: [],
      bindings: [],
      artifactContracts: [
        {
          workflowId: 'design-build',
          stepId: 'design',
          artifacts: [{ ref: 'docs/design.md', requiredHeadings: ['目标', '验收'] }],
        },
        {
          workflowId: 'design-build',
          stepId: 'build',
          artifacts: [],
          noArtifactsReason: '此样例的下游只读取设计，不产生新文件。',
        },
      ],
    },
    composition: {
      kind: 'standalone',
      executorIds: ['local'],
      validatorRefs: [{ id: 'actual-design', version: '1' }],
      transitionHandlers: [],
      workflows: [
        {
          id: 'design-build',
          version: '1',
          entry: 'design',
          steps: {
            design: {
              type: 'handoff',
              ref: 'designer',
              validator: { id: 'actual-design', version: '1' },
              outputSchema: { type: 'object' },
            },
            build: { type: 'handoff', ref: 'builder' },
          },
          transitions: [{ from: 'design', to: 'build' }],
        },
      ],
    },
    modules: {
      'bindings.mjs': `import fs from 'node:fs/promises'; import path from 'node:path'; export function createBindings(context) { return {executors:[{id:'local',capabilities:[],supports:()=>true,execute:async()=>({status:'succeeded',output:{}})}],validators:[{id:'actual-design',version:'1',validate:async()=>({accepted:${alwaysPass ? 'true' : "(await fs.readFile(path.join(context.projectRoot,'docs/design.md'),'utf8')).includes('业务已完成')"},reason:'设计缺少实际业务结果'})}]}; }`,
    },
    artifactTests: [
      {
        workflowId: 'design-build',
        stepId: 'design',
        output: {},
        files: { 'docs/design.md': good },
        invalidCases: [
          {
            name: 'wrong-business-content',
            files: { 'docs/design.md': good.replace('业务已完成', '业务未完成') },
          },
        ],
      },
    ],
  };
}
async function compile(p: WorkflowApplicationProposal) {
  const plan = await prepareWorkflowApplicationPlan({
    proposal: p,
    projectRoot: project,
    packageRoot: path.join(project, 'preview'),
  });
  const compiled = await compileWorkflowApplication({
    plan,
    confirmationHash: hashRuntimeValue(plan),
    projectRoot: project,
    packageRoot: path.join(project, 'compiled'),
  });
  return { plan, compiled };
}
it('checks valid artifacts and real missing, empty, changed, malformed and business negatives in isolation', async () => {
  const { plan, compiled } = await compile(proposal());
  const report = await verifyWorkflowApplicationArtifactContracts({
    plan,
    file: compiled.file,
    packageHash: compiled.contentHash,
  });
  expect(report.checks.map((c) => c.name)).toEqual([
    'valid',
    'missing:docs/design.md',
    'empty:docs/design.md',
    'invalid-content:docs/design.md',
    'changed:docs/design.md',
    'wrong-business-content',
  ]);
  expect(report.checks.filter((c) => c.accepted)).toHaveLength(1);
  expect(await fs.stat(path.join(project, 'docs')).catch(() => null)).toBeNull();
});

function conversationProposal(stopAtApproval = false): WorkflowApplicationProposal {
  const p = proposal();
  p.composition = {
    kind: 'standalone',
    executorIds: ['local'],
    validatorRefs: [],
    transitionHandlers: [],
    workflows: [
      {
        id: 'chain',
        version: '1',
        entry: 'grill',
        steps: {
          grill: { type: 'child_workflow', workflow: { id: 'conversation', version: '1' } },
          implement: { type: 'handoff', ref: 'implement' },
        },
        transitions: [{ from: 'grill', to: 'implement' }],
      },
      {
        id: 'conversation',
        version: '1',
        entry: 'talk',
        steps: {
          talk: { type: 'handoff', ref: 'talk' },
          approve: { type: 'ask_user', proposalFrom: 'talk', choices: ['approved', 'rejected'] },
          complete: { type: 'handoff', ref: 'complete' },
